<?php
require_once __DIR__ . '/db.php';

if (!isset($_SESSION['user_id'])) {
    header('Location: login.php');
    exit;
}

$loan_id = (int) ($_GET['loan_id'] ?? 0);
$is_admin = ($_SESSION['role'] ?? '') === 'admin';
$query = "SELECT l.*, m.user_id, m.first_name, m.last_name, m.email, m.phone, m.member_number FROM loans l JOIN members m ON m.id = l.member_id WHERE l.id = ?";
$parameters = [$loan_id];
if (!$is_admin) {
    $query .= ' AND m.user_id = ?';
    $parameters[] = (int) $_SESSION['user_id'];
}
$stmt = $pdo->prepare($query);
$stmt->execute($parameters);
$loan = $stmt->fetch();
if (!$loan) {
    http_response_code(404);
    exit('Loan application not found.');
}
?>
